    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the core defining feature that differentiates Anorexia Nervosa from Bulimia Nervosa?', '["Binge eating", "Significantly low body weight (BMI usually < 18.5) due to restriction of energy intake", "Purging behaviors", "Disturbance in body image"]', 1, 'Anorexia requires a significantly low body weight. Bulimia patients are typically normal weight or overweight. (DSM-5)'),
    (v_topic_id, '2: Which of the following is a required diagnostic criterion for Anorexia Nervosa?', '["Amenorrhea", "Intense fear of gaining weight or becoming fat, even though at a significantly low weight", "Binge eating", "Purging"]', 1, 'Amenorrhea was removed as a requirement in DSM-5 to include males and post-menopausal women. (First Aid)'),
    (v_topic_id, '3: What are the two subtypes of Anorexia Nervosa?', '["Restricting type and Binge-eating/purging type", "Mild and Severe", "Childhood and Adult onset", "Primary and Secondary"]', 0, 'Restricting type uses dieting/fasting/exercise. Binge/purge type uses vomiting/laxatives but remains underweight. (Kaplan & Sadock)'),
    (v_topic_id, '4: A patient with Anorexia Nervosa, Binge-eating/purging type, differs from a patient with Bulimia Nervosa primarily by:', '["The frequency of binges", "Their significantly low body weight", "The use of laxatives", "The presence of body dysmorphia"]', 1, 'If the patient is underweight, the diagnosis is Anorexia, regardless of bingeing or purging. (MGH Pocket)'),
    (v_topic_id, '5: Which of the following is a common physical exam finding in severe Anorexia Nervosa?', '["Tachycardia", "Lanugo (fine, downy body hair)", "Hypertension", "Fever"]', 1, 'Lanugo grows as the body attempts to insulate itself due to loss of body fat. (First Aid)'),
    (v_topic_id, '6: What cardiovascular complication is most commonly seen in Anorexia Nervosa?', '["Atrial fibrillation", "Sinus bradycardia and hypotension", "Ventricular tachycardia", "Aortic dissection"]', 1, 'Bradycardia is a physiological adaptation to starvation (decreased metabolic rate). (Kaplan & Sadock)'),
    (v_topic_id, '7: Which electrolyte abnormality is classically associated with purging behavior (vomiting) in Eating Disorders?', '["Hyperkalemia", "Hypokalemia, hypochloremia, and metabolic alkalosis", "Hypernatremia", "Hypocalcemia"]', 1, 'Loss of gastric acid (HCl) leads to metabolic alkalosis, and volume depletion triggers aldosterone, wasting potassium. (First Aid)'),
    (v_topic_id, '8: What is "Russell''s sign"?', '["Enlarged parotid glands", "Calluses or abrasions on the dorsum of the hand/knuckles from self-induced vomiting", "Erosion of dental enamel", "Fine body hair"]', 1, 'Caused by repetitive contact between the teeth and the hand during gagging. (MGH Pocket)'),
    (v_topic_id, '9: Dental enamel erosion in a patient with an eating disorder is most likely due to:', '["Starvation", "Frequent exposure to gastric acid from repeated self-induced vomiting", "Lack of calcium", "Chewing ice"]', 1, 'Often seen on the lingual surface of the upper front teeth. (Kaplan & Sadock)'),
    (v_topic_id, '10: Bilateral parotid gland hypertrophy (sialadenosis) is a classic sign of:', '["Anorexia, restricting type", "Chronic self-induced vomiting (often in Bulimia or Anorexia binge/purge type)", "Binge Eating Disorder", "ARFID"]', 1, 'Causes the classic "chipmunk facies" appearance. (First Aid)'),
    (v_topic_id, '11: Which endocrine abnormality is commonly seen in Anorexia Nervosa?', '["Hyperthyroidism", "Hypothalamic amenorrhea (decreased GnRH, LH, and FSH) and decreased estrogen", "Hyperinsulinemia", "Adrenal insufficiency"]', 1, 'Starvation shuts down the reproductive axis to conserve energy. (Kaplan & Sadock)'),
    (v_topic_id, '12: What happens to cortisol levels in severe Anorexia Nervosa?', '["They decrease", "They are elevated (hypercortisolemia) due to the physiological stress of starvation", "They remain normal", "They fluctuate wildly"]', 1, 'The body is in a state of chronic stress. (MGH Pocket)'),
    (v_topic_id, '13: What happens to thyroid hormone levels in Anorexia Nervosa?', '["Elevated TSH", "Euthyroid sick syndrome (low normal T3, normal T4, normal TSH)", "Primary hypothyroidism", "Hyperthyroidism"]', 1, 'The body reduces active T3 to slow metabolism and conserve energy. (First Aid)'),
    (v_topic_id, '14: Which of the following is a dreaded and potentially fatal complication of nutritional rehabilitation in severely malnourished patients?', '["Serotonin Syndrome", "Refeeding Syndrome", "Neuroleptic Malignant Syndrome", "Hypertensive crisis"]', 1, 'Rapid reintroduction of carbohydrates triggers insulin release, driving electrolytes intracellularly. (Kaplan & Sadock)'),
    (v_topic_id, '15: What is the classic electrolyte triad of Refeeding Syndrome?', '["Hyperkalemia, hypermagnesemia, hyperphosphatemia", "Hypophosphatemia, hypokalemia, and hypomagnesemia", "Hyponatremia, hypocalcemia, hypochloremia", "None"]', 1, 'Hypophosphatemia is the hallmark and can lead to fatal arrhythmias and heart failure. (First Aid)'),
    (v_topic_id, '16: Why does hypophosphatemia occur in Refeeding Syndrome?', '["Kidney failure", "Insulin surge causes rapid intracellular shift of phosphate for ATP synthesis, depleting serum levels", "Poor diet", "Vomiting"]', 1, 'ATP production demands massive amounts of phosphate. (MGH Pocket)'),
    (v_topic_id, '17: What cardiac complication is most directly caused by the hypophosphatemia in Refeeding Syndrome?', '["Aortic stenosis", "Myocardial dysfunction/heart failure and arrhythmias", "Endocarditis", "Pericarditis"]', 1, 'The heart muscle lacks ATP to pump effectively. (Kaplan & Sadock)'),
    (v_topic_id, '18: What is the first-line and most effective treatment for Anorexia Nervosa?', '["Fluoxetine", "Nutritional rehabilitation and psychotherapy (e.g., Family-Based Treatment for adolescents)", "Olanzapine", "Lithium"]', 1, 'Medications are generally ineffective until the patient gains weight. (First Aid)'),
    (v_topic_id, '19: Why are SSRIs generally considered ineffective in acute, low-weight Anorexia Nervosa?', '["They cause weight loss", "The starved brain lacks the necessary dietary precursors (tryptophan) to synthesize serotonin", "They cause seizures", "They increase purging"]', 1, 'SSRIs may be useful for comorbid depression/anxiety ONLY after weight is restored. (MGH Pocket)'),
    (v_topic_id, '20: Which atypical antipsychotic is sometimes used off-label in severe Anorexia Nervosa to help with weight gain and obsessive thoughts about food?', '["Haloperidol", "Olanzapine", "Clozapine", "Ziprasidone"]', 1, 'Olanzapine promotes weight gain and can reduce the rigid, delusional-level body image distortions. (Kaplan & Sadock)'),
    (v_topic_id, '21: What bone complication is highly prevalent in chronic Anorexia Nervosa?', '["Osteosarcoma", "Osteopenia and Osteoporosis due to low estrogen and elevated cortisol", "Paget''s disease", "Osteopetrosis"]', 1, 'Often irreversible if peak bone mass is not achieved during adolescence. (First Aid)'),
    (v_topic_id, '22: How should osteoporosis in Anorexia Nervosa be treated?', '["Estrogen replacement (OCPs)", "Weight restoration is the only definitively effective treatment; OCPs do not reverse the bone loss", "Bisphosphonates", "Vitamin C"]', 1, 'OCPs give a false sense of security by inducing withdrawal bleeding without fixing the bones. (MGH Pocket)'),
    (v_topic_id, '23: Which psychiatric comorbidity has the highest prevalence in patients with Anorexia Nervosa?', '["Schizophrenia", "Obsessive-Compulsive Disorder (OCD) and Major Depressive Disorder", "Bipolar I", "PTSD"]', 1, 'Obsessive traits are highly ego-syntonic in the restricting subtype. (Kaplan & Sadock)'),
    (v_topic_id, '24: What is the mortality rate of Anorexia Nervosa compared to other psychiatric illnesses?', '["Very low", "It has the highest mortality rate of any psychiatric disorder (up to 10-20% in long-term studies)", "Average", "Zero"]', 1, 'Death is usually due to medical complications (arrhythmias) or suicide. (First Aid)'),
    (v_topic_id, '25: Bulimia Nervosa is characterized by recurrent episodes of binge eating followed by:', '["Sleeping", "Inappropriate compensatory behaviors (purging, fasting, excessive exercise) to prevent weight gain", "Amnesia", "None"]', 1, 'The binge-purge cycle is the core of the disorder. (DSM-5)'),
    (v_topic_id, '26: According to DSM-5, how frequently must binge eating and compensatory behaviors occur to diagnose Bulimia Nervosa?', '["Once a month", "At least once a week for 3 months", "Every day for 1 month", "Twice a week for 6 months"]', 1, 'Frequency criterion. (Kaplan & Sadock)'),
    (v_topic_id, '27: What defines a "binge"?', '["Eating a lot of food", "Eating an objectively large amount of food in a discrete period of time AND a sense of lack of control during the episode", "Eating fast", "None"]', 1, 'Loss of control is a mandatory psychological component. (First Aid)'),
    (v_topic_id, '28: What is the typical body weight of a patient with Bulimia Nervosa?', '["Significantly underweight", "Normal weight or slightly overweight", "Morbidly obese", "None"]', 1, 'This is the key differentiator from Anorexia binge/purge subtype. (MGH Pocket)'),
    (v_topic_id, '29: A patient with Bulimia Nervosa uses laxatives heavily. What acid-base disturbance is expected?', '["Metabolic alkalosis", "Normal gap metabolic acidosis with hypokalemia", "Respiratory alkalosis", "Respiratory acidosis"]', 1, 'Diarrhea causes loss of bicarbonate (base) from the lower GI tract. (First Aid)'),
    (v_topic_id, '30: A patient with Bulimia uses vomiting heavily. What acid-base disturbance is expected?', '["Metabolic acidosis", "Metabolic alkalosis with hypokalemia and hypochloremia", "Respiratory alkalosis", "None"]', 1, 'Vomiting loses HCl (acid) from the stomach. (Kaplan & Sadock)'),
    (v_topic_id, '31: Which medication is FDA-approved and considered first-line pharmacotherapy for Bulimia Nervosa?', '["Lithium", "Fluoxetine (an SSRI)", "Valproate", "Haloperidol"]', 1, 'High doses (e.g., 60mg/day) are often required to reduce binge/purge frequency. (MGH Pocket)'),
    (v_topic_id, '32: Which medication is strictly CONTRAINDICATED in patients with Bulimia Nervosa or Anorexia Nervosa?', '["Fluoxetine", "Bupropion", "Sertraline", "Mirtazapine"]', 1, 'Bupropion lowers the seizure threshold, and these patients are already at high risk for seizures due to electrolyte imbalances. (First Aid)'),
    (v_topic_id, '33: What is the first-line psychotherapy for Bulimia Nervosa?', '["Psychoanalysis", "Cognitive Behavioral Therapy (CBT)", "Exposure therapy", "EMDR"]', 1, 'CBT specifically tailored for eating disorders (CBT-E) is highly effective. (Kaplan & Sadock)'),
    (v_topic_id, '34: What is Binge-Eating Disorder (BED)?', '["Binge eating with purging", "Recurrent episodes of binge eating WITHOUT inappropriate compensatory behaviors", "Just overeating", "None"]', 1, 'Patients do not purge, fast, or excessively exercise after binges. (DSM-5)'),
    (v_topic_id, '35: What is the typical body weight of a patient with Binge-Eating Disorder?', '["Underweight", "Normal weight, overweight, or obese (most commonly overweight/obese)", "Extremely underweight", "None"]', 1, 'Because there are no compensatory behaviors to offset the caloric intake. (MGH Pocket)'),
    (v_topic_id, '36: Which of the following is a criterion for Binge-Eating Disorder?', '["Eating very slowly", "Eating until feeling uncomfortably full, eating when not physically hungry, or eating alone due to embarrassment", "Purging", "None"]', 1, 'The binges are associated with significant distress, guilt, and disgust. (First Aid)'),
    (v_topic_id, '37: Which medication is FDA-approved for the treatment of moderate-to-severe Binge-Eating Disorder?', '["Lisdexamfetamine (Vyvanse)", "Fluoxetine", "Bupropion", "Lorazepam"]', 1, 'A stimulant that helps reduce binge frequency; SSRIs can also be used off-label. (Kaplan & Sadock)'),
    (v_topic_id, '38: What is Avoidant/Restrictive Food Intake Disorder (ARFID)?', '["Anorexia in kids", "An eating/feeding disturbance (e.g., lack of interest in food, sensory aversion) leading to failure to meet nutritional needs, WITHOUT body image distortion", "Pica", "None"]', 1, 'They don''t eat because they hate the texture/smell or fear choking, NOT because they fear getting fat. (DSM-5)'),
    (v_topic_id, '39: A 7-year-old boy refuses to eat anything except white bread and chicken nuggets because he gags at the texture of vegetables and meat. He is falling off his growth curve. Diagnosis?', '["Anorexia Nervosa", "Avoidant/Restrictive Food Intake Disorder (ARFID)", "Bulimia", "Normal picky eating"]', 1, 'Classic sensory-based ARFID. (First Aid)'),
    (v_topic_id, '40: How does ARFID differ from normal "picky eating" in childhood?', '["It doesn''t", "ARFID results in significant weight loss, nutritional deficiency, or dependence on enteral feeding/supplements", "Picky eaters throw tantrums", "None"]', 1, 'Impairment is the key. (MGH Pocket)'),
    (v_topic_id, '41: What is Pica?', '["Eating too much", "Persistent eating of non-nutritive, non-food substances (e.g., dirt, paint, ice) for at least 1 month", "Vomiting", "None"]', 1, 'Must be developmentally inappropriate (e.g., normal in a 1-year-old, pathological in an adult). (DSM-5)'),
    (v_topic_id, '42: Pica is highly associated with which nutritional deficiency?', '["Vitamin C", "Iron deficiency anemia or Zinc deficiency", "Vitamin B12", "Calcium"]', 1, 'Pagophagia (eating ice) is very specific for iron deficiency. (First Aid)'),
    (v_topic_id, '43: What is Rumination Disorder?', '["Thinking too much", "Repeated regurgitation of food (which may be re-chewed, re-swallowed, or spit out) for at least 1 month, not due to a GI condition", "Vomiting from nausea", "None"]', 1, 'Usually effortless and not accompanied by nausea or disgust. (Kaplan & Sadock)'),
    (v_topic_id, '44: Which behavioral therapy is used for Rumination Disorder?', '["Psychoanalysis", "Diaphragmatic breathing (habit reversal training)", "Exposure therapy", "None"]', 1, 'Breathing techniques prevent the abdominal muscle contractions needed to regurgitate. (MGH Pocket)'),
    (v_topic_id, '45: A patient with Anorexia Nervosa presents with peripheral edema. What is the most likely cause?', '["Heart failure only", "Hypoalbuminemia due to severe protein malnutrition (decreased oncotic pressure)", "Renal failure", "Liver failure"]', 1, 'A classic sign of starvation (similar to Kwashiorkor). (First Aid)'),
    (v_topic_id, '46: What hematologic abnormality is commonly seen in severe Anorexia Nervosa?', '["Polycythemia", "Pancytopenia (leukopenia, anemia, thrombocytopenia) due to bone marrow hypoplasia/starvation", "Leukocytosis", "Thrombocytosis"]', 1, 'The bone marrow undergoes gelatinous transformation due to lack of energy. (Kaplan & Sadock)'),
    (v_topic_id, '47: What happens to cholesterol levels in Anorexia Nervosa?', '["They drop to zero", "Paradoxical hypercholesterolemia", "They are normal", "None"]', 1, 'Due to decreased cholesterol metabolism and altered hepatic function despite low fat intake. (MGH Pocket)'),
    (v_topic_id, '48: Which GI complication is extremely common in patients with Anorexia Nervosa?', '["Diarrhea", "Delayed gastric emptying (gastroparesis) and severe constipation", "Peptic ulcer disease", "Crohn''s disease"]', 1, 'The gut slows down to extract maximum nutrients and conserve energy. Causes bloating when they try to eat. (First Aid)'),
    (v_topic_id, '49: A patient with Bulimia Nervosa complains of sudden, severe, tearing chest pain after a bout of violent vomiting. What is the catastrophic complication?', '["Mallory-Weiss tear", "Boerhaave syndrome (esophageal rupture)", "Myocardial infarction", "Pneumothorax"]', 1, 'A surgical emergency. Mallory-Weiss is mucosal (bleeding); Boerhaave is transmural (rupture). (Kaplan & Sadock)'),
    (v_topic_id, '50: A patient with Bulimia Nervosa presents with hematemesis after vomiting. What is the most likely cause?', '["Boerhaave syndrome", "Mallory-Weiss tear (mucosal laceration at the gastroesophageal junction)", "Varices", "Gastric ulcer"]', 1, 'Usually self-limiting but requires medical evaluation. (First Aid)'),
    (v_topic_id, '51: What ECG change is classically associated with the hypokalemia seen in eating disorders?', '["Peaked T waves", "U waves, flattened T waves, and ST depression", "Widened QRS", "Shortened QT interval"]', 1, 'Can progress to dangerous arrhythmias. (MGH Pocket)'),
    (v_topic_id, '52: What happens to the QT interval in severe Anorexia Nervosa?', '["It shortens", "It prolongs (QTc prolongation), increasing the risk of Torsades de Pointes", "It stays normal", "None"]', 1, 'Due to hypokalemia, hypomagnesemia, and starvation-induced myocardial changes. (Kaplan & Sadock)'),
    (v_topic_id, '53: When should a patient with Anorexia Nervosa be hospitalized against their will?', '["Never", "If there is imminent medical instability (e.g., HR < 40, BP < 80/50, temp < 35C, severe electrolyte derangement, or weight < 70% of ideal body weight)", "Only if they ask", "None"]', 1, 'Medical necessity overrides autonomy in life-threatening starvation. (First Aid)'),
    (v_topic_id, '54: In Family-Based Treatment (FBT) or "Maudsley Approach" for adolescents with Anorexia, what is the initial phase?', '["The adolescent cooks", "Parents take complete control over the adolescent''s meals and eating to achieve weight restoration", "Individual therapy", "None"]', 1, 'The illness is externalized, and parents are empowered to refeed their child. (MGH Pocket)'),
    (v_topic_id, '55: What is the role of Topiramate in eating disorders?', '["Treats Anorexia", "Used off-label to reduce binge eating and promote weight loss in Binge-Eating Disorder or Bulimia", "Causes weight gain", "None"]', 1, 'Can cause cognitive dulling ("dopamax") and paresthesias. (Kaplan & Sadock)'),
    (v_topic_id, '56: A patient with Bulimia Nervosa has normal potassium today but reports daily vomiting. What urine test can confirm chronic vomiting?', '["Urine sodium", "Urine chloride (will be very low, <20 mEq/L, as the kidneys hold onto chloride to compensate for gastric HCl loss)", "Urine glucose", "Urine ketones"]', 1, 'A classic board pearl for hidden vomiting. (First Aid)'),
    (v_topic_id, '57: A patient with a BMI of 16 engages in weekly binge eating and self-induced vomiting. Diagnosis?', '["Bulimia Nervosa", "Anorexia Nervosa, Binge-eating/purging type", "Binge-Eating Disorder", "None"]', 1, 'BMI < 18.5 dictates the Anorexia diagnosis. (MGH Pocket)'),
    (v_topic_id, '58: A patient with a BMI of 22 engages in weekly binge eating and self-induced vomiting. Diagnosis?', '["Anorexia Nervosa", "Bulimia Nervosa", "Binge-Eating Disorder", "None"]', 1, 'Normal weight dictates the Bulimia diagnosis. (Kaplan & Sadock)'),
    (v_topic_id, '59: A patient with a BMI of 30 engages in weekly binge eating but never vomits, fasts, or exercises. Diagnosis?', '["Bulimia Nervosa", "Binge-Eating Disorder", "Anorexia", "None"]', 1, 'Absence of compensatory behaviors. (First Aid)'),
    (v_topic_id, '60: What happens to serum amylase in Bulimia Nervosa?', '["It decreases", "It is often elevated (hyperamylasemia) due to salivary gland hypertrophy from chronic vomiting", "It is zero", "None"]', 1, 'Lipase will be normal (differentiating it from pancreatitis). (MGH Pocket)'),
    (v_topic_id, '61: How does Anorexia Nervosa affect brain imaging (MRI)?', '["Tumors", "Cerebral atrophy with enlarged ventricles and widened sulci (pseudoatrophy)", "Hemorrhage", "None"]', 1, 'Often reverses with weight restoration. (Kaplan & Sadock)'),
    (v_topic_id, '62: Patients with eating disorders often exhibit "Alexithymia." What does this mean?', '["Fear of eating", "An inability to identify and express one''s emotions verbally", "Fear of words", "None"]', 1, 'They use food/starvation to cope because they cannot articulate their feelings. (First Aid)'),
    (v_topic_id, '63: A common defense mechanism in Anorexia Nervosa is:', '["Acting out", "Denial (profound denial of the severity of their low body weight or illness)", "Humor", "None"]', 1, 'They often insist they are "perfectly healthy." (MGH Pocket)'),
    (v_topic_id, '64: What is the typical age of onset for Anorexia Nervosa?', '["Early childhood", "Adolescence or young adulthood (peaks at ages 14 and 18)", "Middle age", "Late adulthood"]', 1, 'Often coincides with puberty and transition to high school/college. (Kaplan & Sadock)'),
    (v_topic_id, '65: Which gender is more commonly affected by Anorexia and Bulimia?', '["Men", "Women (approx 10:1 ratio compared to men)", "Equal", "None"]', 1, 'Though prevalence in males is increasingly recognized, particularly in certain sports (e.g., wrestling). (First Aid)'),
    (v_topic_id, '66: A pregnant woman eats dirt from her garden daily. She has normal body image. Diagnosis?', '["Anorexia", "Pica", "Bulimia", "None"]', 1, 'Check her iron/hemoglobin levels immediately. (MGH Pocket)'),
    (v_topic_id, '67: What physical sign on the hands is associated with chronic starvation in Anorexia?', '["Clubbing", "Acrocyanosis (blue, cold hands and feet) and brittle nails", "Erythema", "None"]', 1, 'Due to poor circulation and sympathetic overactivity in an attempt to retain heat. (Kaplan & Sadock)'),
    (v_topic_id, '68: Which of the following sports/professions carries the highest risk for Anorexia Nervosa?', '["Football", "Ballet, gymnastics, figure skating, wrestling, and modeling", "Baseball", "None"]', 1, 'Activities where lean body shape or weight classes are highly emphasized. (First Aid)'),
    (v_topic_id, '69: The "Female Athlete Triad" consists of:', '["Anemia, fatigue, cramps", "Low energy availability (with or without an eating disorder), amenorrhea, and decreased bone mineral density (osteoporosis)", "None", "None"]', 1, 'A crucial concept in sports medicine. (MGH Pocket)'),
    (v_topic_id, '70: A patient with Anorexia complains of diffuse hair loss. This is called:', '["Alopecia areata", "Telogen effluvium (diffuse shedding of hair due to severe physiological stress/starvation)", "Traction alopecia", "None"]', 1, 'The hair follicles enter the resting phase to conserve protein. (Kaplan & Sadock)'),
    (v_topic_id, '71: What happens to BUN levels in Anorexia Nervosa?', '["They decrease", "They may be elevated due to dehydration (pre-renal azotemia)", "They stay normal", "None"]', 1, 'Dehydration is very common due to poor fluid intake or purging. (First Aid)'),
    (v_topic_id, '72: What is "Diabulimia"?', '["Eating sugar", "A colloquial term for when patients with Type 1 Diabetes intentionally skip or reduce insulin doses to induce glycosuria and weight loss", "Taking too much insulin", "None"]', 1, 'Extremely dangerous; high risk of DKA. (MGH Pocket)'),
    (v_topic_id, '73: A patient with Bulimia Nervosa engages in heavy exercise. How is "excessive exercise" defined?",', '["Working out daily", "Exercise that significantly interferes with important activities, occurs at inappropriate times/settings, or continues despite injury", "None", "None"]', 1, 'It is driven by a compulsion to burn calories, not for fitness. (Kaplan & Sadock)'),
    (v_topic_id, '74: Are patients with Bulimia Nervosa generally distressed by their behavior?', '["No", "Yes, their binge/purge behavior is highly egodystonic (they feel immense guilt, shame, and disgust)", "None", "None"]', 1, 'This makes them more likely to seek treatment than Anorexia restricting type. (First Aid)'),
    (v_topic_id, '75: A severe complication of chronic laxative abuse is:', '["Diarrhea", "Cathartic colon (loss of normal colonic peristalsis, resulting in severe chronic constipation when laxatives are stopped)", "Colon cancer", "None"]', 1, 'The colon becomes a flaccid tube dependent on chemical stimulation. (MGH Pocket)'),
    (v_topic_id, '76: A patient with Bulimia presents with sudden muscle weakness and cramps. Most likely cause?', '["Tetanus", "Severe hypokalemia", "Hypercalcemia", "None"]', 1, 'Low potassium impairs muscle contraction. (Kaplan & Sadock)'),
    (v_topic_id, '77: Which neurotransmitter system is most heavily implicated in the pathogenesis of Anorexia Nervosa?', '["Dopamine", "Serotonin (5-HT); patients often have altered 5-HT receptor activity contributing to dysphoria and obsessiveness", "GABA", "None"]', 1, 'Starvation temporarily decreases 5-HT, which paradoxically reduces their baseline anxiety. (First Aid)'),
    (v_topic_id, '78: In a patient with Anorexia, how should caloric refeeding be initiated?', '["10,000 kcal/day", "Slowly (e.g., 1200-1500 kcal/day initially) and gradually increased, to prevent Refeeding Syndrome", "Only via IV", "None"]', 1, 'Close monitoring of phosphorus, potassium, and magnesium is required. (MGH Pocket)'),
    (v_topic_id, '79: Can men be diagnosed with Anorexia Nervosa?', '["No", "Yes, and they often present with a focus on ''''muscle dysmorphia'''' or extreme leanness rather than simply wanting to be ''''thin''''", "None", "None"]', 1, 'A growing population in eating disorder clinics. (Kaplan & Sadock)'),
    (v_topic_id, '80: A 19-year-old girl has a BMI of 18.0. She restricts her food severely but does not binge or purge. She has not had a period in 6 months. Diagnosis?', '["Bulimia", "Anorexia Nervosa, Restricting Type", "ARFID", "None"]', 1, 'Meets all criteria for the restricting subtype. (First Aid)'),
    (v_topic_id, '81: A patient with Anorexia has carotene pigmentation. What does this look like?', '["Blue skin", "Yellowing of the skin (carotenemia), especially on the palms and soles, but sparing the sclera", "Red skin", "None"]', 1, 'Due to diets heavy in low-calorie, carotene-rich foods (carrots) or acquired defect in carotene metabolism. (MGH Pocket)'),
    (v_topic_id, '82: What is the difference between carotenemia in Anorexia and jaundice?",', '["They are the same", "Carotenemia SPARES the sclera (eyes remain white). Jaundice turns the sclera yellow.", "None", "None"]', 1, 'A classic physical exam distinction. (Kaplan & Sadock)'),
    (v_topic_id, '83: What personality traits are highly correlated with Anorexia Nervosa, Restricting Type?', '["Impulsivity, erratic behavior", "Perfectionism, rigidity, harm avoidance, and obsessive-compulsive traits", "Aggression", "None"]', 1, 'They are the "rule followers." (First Aid)'),
    (v_topic_id, '84: What personality traits are highly correlated with Bulimia Nervosa?', '["Rigidity", "Impulsivity, novelty seeking, and emotional dysregulation (highly comorbid with Borderline Personality Disorder)", "Shyness", "None"]', 1, 'The loss of control in binges mirrors their general impulsivity. (MGH Pocket)'),
    (v_topic_id, '85: A patient with Bulimia uses ipecac syrup to induce vomiting. What is the specific toxicity risk of chronic ipecac use?', '["Liver failure", "Irreversible cardiac toxicity (cardiomyopathy and heart failure) due to accumulation of emetine", "Blindness", "None"]', 1, 'Ipecac is no longer sold over-the-counter for this exact reason. (Kaplan & Sadock)'),
    (v_topic_id, '86: Which eating disorder has the highest prevalence in the general US population?', '["Anorexia", "Binge-Eating Disorder (BED)", "Bulimia", "None"]', 1, 'BED is the most common eating disorder. (First Aid)'),
    (v_topic_id, '87: What is the long-term prognosis for Anorexia Nervosa?', '["100% cure rate", "Rule of thirds: 1/3 fully recover, 1/3 have partial recovery/relapses, 1/3 remain chronically ill", "0% cure rate", "None"]', 1, 'It is a chronic, relapsing condition for many. (MGH Pocket)'),
    (v_topic_id, '88: Which psychological test is commonly used to assess eating disorder pathology?', '["MMPI", "Eating Attitudes Test (EAT-26) or the Eating Disorder Examination (EDE)", "PHQ-9", "None"]', 1, 'Standardized tools for research and clinical tracking. (Kaplan & Sadock)'),
    (v_topic_id, '89: In the treatment of Bulimia Nervosa, what is the goal of CBT?', '["To find childhood trauma", "To identify triggers for bingeing, challenge distorted beliefs about shape/weight, and establish regular eating patterns", "To force weight gain", "None"]', 1, 'Focuses on the cognitive distortions maintaining the cycle. (First Aid)'),
    (v_topic_id, '90: What is the physiological cause of the "chipmunk facies" in Bulimia?', '["Fat accumulation", "Non-inflammatory hypertrophy of the salivary (parotid) glands due to hyperstimulation from frequent vomiting", "Infection", "None"]', 1, 'Usually painless and bilateral. (MGH Pocket)'),
    (v_topic_id, '91: A patient with Anorexia is admitted to the hospital. On day 3, she develops severe edema, shortness of breath, and a phosphorus level of 1.2 mg/dL. Diagnosis?', '["Pneumonia", "Refeeding Syndrome", "Sepsis", "None"]', 1, 'A life-threatening emergency requiring immediate ICU care. (Kaplan & Sadock)'),
    (v_topic_id, '92: What supplement is critical to give prophylacticly when refeeding a starved patient?', '["Vitamin C", "Thiamine (Vitamin B1) to prevent Wernicke''s encephalopathy, along with multivitamins", "Iron", "None"]', 1, 'Carbohydrate load depletes remaining thiamine stores. (First Aid)'),
    (v_topic_id, '93: How is ARFID differentiated from Anorexia Nervosa?', '["ARFID patients binge", "ARFID patients have NO distorted body image and NO intense fear of gaining weight; they simply avoid food for sensory/fear reasons", "They are the same", "None"]', 1, 'The psychological intent is completely different. (MGH Pocket)'),
    (v_topic_id, '94: A patient with BED eats 5,000 calories in 2 hours and feels disgusted. What is the most appropriate next step in management?', '["Bariatric surgery", "Cognitive Behavioral Therapy (CBT) and consideration of SSRIs or Lisdexamfetamine", "Fasting", "None"]', 1, 'Treat the psychiatric disorder before addressing weight loss. (Kaplan & Sadock)'),
    (v_topic_id, '95: Does Bulimia Nervosa require the patient to purge (vomit)?', '["Yes, always", "No, compensatory behaviors can be non-purging (e.g., fasting for 2 days after a binge, or running 10 miles)", "None", "None"]', 1, 'Purging is common but not mandatory for the diagnosis. (First Aid)'),
    (v_topic_id, '96: What is the most common trigger for a binge episode in Bulimia Nervosa?', '["Happiness", "Negative affect (e.g., feeling sad, anxious, or bored) or interpersonal stress", "Exercise", "None"]', 1, 'The binge is an emotional regulation tool. (MGH Pocket)'),
    (v_topic_id, '97: Why is Bupropion absolutely contraindicated in Anorexia and Bulimia?', '["It causes weight gain", "It lowers the seizure threshold, and these patients have electrolyte abnormalities that already predispose them to seizures", "It causes liver failure", "None"]', 1, 'A classic, high-yield board question. (Kaplan & Sadock)'),
    (v_topic_id, '98: A patient with Anorexia has a fine, soft hair covering her arms, back, and face. This is:', '["Hirsutism", "Lanugo", "Alopecia", "None"]', 1, 'The body''s attempt to stay warm. (First Aid)'),
    (v_topic_id, '99: Which of the following is a criterion for Anorexia Nervosa severity in DSM-5?', '["Frequency of binges", "Body Mass Index (BMI). Mild > 17, Moderate 16-16.9, Severe 15-15.9, Extreme < 15.", "Blood pressure", "None"]', 1, 'Severity is strictly anchored to BMI. (MGH Pocket)'),
    (v_topic_id, '100: Which of the following is a criterion for Bulimia Nervosa severity in DSM-5?', '["BMI", "Frequency of inappropriate compensatory behaviors per week (Mild 1-3, Moderate 4-7, Severe 8-13, Extreme 14+)", "Heart rate", "None"]', 1, 'Severity is anchored to behavior frequency, not weight. (Kaplan & Sadock)'),
    (v_topic_id, '101: What is the primary focus of Family-Based Treatment (FBT) for Anorexia Nervosa?', '["Exploring childhood trauma", "Empowering parents to restore their child''s weight at home", "Prescribing medications", "None"]', 1, 'FBT is the most evidence-based treatment for adolescents with Anorexia. (First Aid)'),
    (v_topic_id, '102: A patient with Anorexia Nervosa is found to have a prolonged QTc interval. What is the most immediate concern?', '["Asthma", "Torsades de Pointes and sudden cardiac death", "Seizures", "None"]', 1, 'Hypokalemia and starvation-induced myocardial changes prolong the QTc. (MGH Pocket)'),
    (v_topic_id, '103: Which eating disorder is most associated with an increased risk of esophageal cancer?', '["Anorexia Restricting Type", "Bulimia Nervosa (due to chronic acid exposure from purging)", "ARFID", "None"]', 1, 'Chronic vomiting leads to Barrett''s esophagus, a precursor to adenocarcinoma. (Kaplan & Sadock)'),
    (v_topic_id, '104: What is the "Russell sign" and what does it indicate?', '["Blue toes", "Calluses on the knuckles from self-induced vomiting", "Red eyes", "None"]', 1, 'A classic physical exam finding in purging behaviors. (First Aid)'),
    (v_topic_id, '105: How does Binge-Eating Disorder differ from Bulimia Nervosa?', '["BED patients eat more", "BED lacks the inappropriate compensatory behaviors (purging, fasting, over-exercising) seen in Bulimia", "They are the same", "None"]', 1, 'The absence of compensation leads to weight gain in BED. (MGH Pocket)'),
    (v_topic_id, '106: What is the most common acid-base disturbance in a patient who frequently abuses laxatives?', '["Metabolic alkalosis", "Normal anion gap metabolic acidosis (due to loss of bicarbonate in stool)", "Respiratory alkalosis", "None"]', 1, 'Diarrhea loses base. Vomiting loses acid. (Kaplan & Sadock)'),
    (v_topic_id, '107: A 15-year-old girl is brought in by her parents for weight loss. She says she feels fat despite a BMI of 16. She denies bingeing or purging. What is the most appropriate initial treatment?', '["Fluoxetine", "Nutritional rehabilitation and Family-Based Treatment (FBT)", "Lithium", "None"]', 1, 'Weight restoration is the primary goal before medications are considered. (First Aid)'),
    (v_topic_id, '108: Which of the following laboratory findings is expected in a patient with severe Anorexia Nervosa?', '["Hyperkalemia", "Leukopenia, anemia, and thrombocytopenia (pancytopenia)", "Hyperglycemia", "None"]', 1, 'Bone marrow suppression occurs due to starvation. (MGH Pocket)'),
    (v_topic_id, '109: A patient with Bulimia Nervosa presents with bilateral parotid swelling. What is the underlying mechanism?', '["Infection", "Hypertrophy from chronic stimulation during vomiting", "Tumor", "None"]', 1, 'A benign, non-inflammatory hypertrophy. (Kaplan & Sadock)'),
    (v_topic_id, '110: What is the diagnostic criteria for Pica?', '["Eating too fast", "Eating nonnutritive, nonfood substances for at least 1 month, inappropriate to the developmental level", "Purging", "None"]', 1, 'Commonly associated with iron or zinc deficiency. (First Aid)'),
    (v_topic_id, '111: A 5-year-old child regurgitates food, re-chews it, and swallows it again. This behavior has occurred for 2 months. Diagnosis?', '["Anorexia", "Rumination Disorder", "Pica", "None"]', 1, 'Often responsive to behavioral therapy like diaphragmatic breathing. (MGH Pocket)'),
    (v_topic_id, '112: Which medication is contraindicated in patients with an active eating disorder due to the risk of seizures?', '["Sertraline", "Bupropion", "Olanzapine", "None"]', 1, 'Electrolyte imbalances already lower the seizure threshold. (Kaplan & Sadock)'),
    (v_topic_id, '113: What is the hallmark electrolyte abnormality of Refeeding Syndrome?', '["Hyperkalemia", "Severe hypophosphatemia", "Hypernatremia", "None"]', 1, 'Insulin surge drives phosphate into cells for ATP synthesis, depleting serum levels. (First Aid)'),
    (v_topic_id, '114: A patient with Anorexia Nervosa has amenorrhea. What is the cause?', '["PCOS", "Hypothalamic suppression leading to low GnRH, LH, FSH, and estrogen", "Pregnancy", "None"]', 1, 'The body shuts down non-essential functions (reproduction) to save energy. (MGH Pocket)'),
    (v_topic_id, '115: What is the most effective psychological treatment for Bulimia Nervosa?', '["Psychoanalysis", "Cognitive Behavioral Therapy (CBT)", "Supportive therapy", "None"]', 1, 'Helps identify triggers and modify distorted thoughts about body weight. (Kaplan & Sadock)'),
    (v_topic_id, '116: A patient with ARFID avoids food because of the texture. How does this differ from Anorexia?",', '["It doesn''t", "ARFID patients do NOT have a distorted body image or fear of weight gain", "ARFID patients are obese", "None"]', 1, 'The motivation for restriction is the key difference. (First Aid)'),
    (v_topic_id, '117: Which medication is FDA-approved for Binge-Eating Disorder?', '["Lithium", "Lisdexamfetamine (Vyvanse)", "Haloperidol", "None"]', 1, 'A stimulant that helps reduce binge frequency. (MGH Pocket)'),
    (v_topic_id, '118: A patient with Anorexia Nervosa develops fine, downy hair on their body. This is called:",', '["Alopecia", "Lanugo", "Hirsutism", "None"]', 1, 'A physiological response to conserve body heat. (Kaplan & Sadock)'),
    (v_topic_id, '119: What is the mortality rate of Anorexia Nervosa?",', '["It is not fatal", "It has the highest mortality rate of any psychiatric disorder, primarily due to cardiac complications and suicide", "Very low", "None"]', 1, 'Requires rigorous medical and psychiatric monitoring. (First Aid)'),
    (v_topic_id, '120: A patient with Bulimia Nervosa has erosion of the dental enamel. This is most likely caused by:",', '["Poor brushing", "Repeated exposure to gastric acid from self-induced vomiting", "Sugar intake", "None"]', 1, 'Often seen on the lingual surfaces of the front teeth. (MGH Pocket)'),
    (v_topic_id, '121: Which personality traits are commonly associated with Anorexia Nervosa (Restricting Type)?",', '["Impulsivity", "Perfectionism, rigidity, and obsessiveness", "Aggression", "None"]', 1, 'They are often high achievers who rigidly follow rules. (Kaplan & Sadock)'),
    (v_topic_id, '122: Which personality traits are commonly associated with Bulimia Nervosa?",', '["Rigidity", "Impulsivity and emotional dysregulation", "Shyness", "None"]', 1, 'Highly comorbid with Borderline Personality Disorder. (First Aid)'),
    (v_topic_id, '123: What is the role of SSRIs in Anorexia Nervosa?",', '["They are first-line", "They are generally ineffective at low weights but may help with comorbid depression/anxiety after weight restoration", "They cause weight gain", "None"]', 1, 'The starved brain lacks tryptophan to make serotonin. (MGH Pocket)'),
    (v_topic_id, '124: A patient with Anorexia Nervosa presents with peripheral edema. What is the likely cause?",', '["Heart failure", "Hypoalbuminemia due to severe protein malnutrition", "Kidney failure", "None"]', 1, 'Decreased oncotic pressure causes fluid to leak into tissues. (Kaplan & Sadock)'),
    (v_topic_id, '125: What is the definition of a "binge" in eating disorders?",', '["Eating a large meal", "Eating an objectively large amount of food with a subjective sense of loss of control", "Eating fast", "None"]', 1, 'The feeling of being out of control is essential to the diagnosis. (First Aid)'),
    (v_topic_id, '126: A patient with an eating disorder uses ipecac syrup to induce vomiting. What is the primary risk?",', '["Diarrhea", "Irreversible cardiomyopathy and heart failure", "Liver failure", "None"]', 1, 'Emetine toxicity damages the heart muscle. (MGH Pocket)'),
    (v_topic_id, '127: Which eating disorder has the highest prevalence in the US?",', '["Anorexia", "Binge-Eating Disorder (BED)", "Bulimia", "None"]', 1, 'Often overlooked but highly prevalent. (Kaplan & Sadock)'),
    (v_topic_id, '128: What is "Diabulimia"?",', '["Eating candy", "Intentional omission of insulin by a Type 1 Diabetic to induce glycosuria and weight loss", "Taking too much insulin", "None"]', 1, 'Carries a very high risk of Diabetic Ketoacidosis (DKA). (First Aid)'),
    (v_topic_id, '129: What happens to thyroid hormones in Anorexia Nervosa?",', '["Elevated TSH", "Euthyroid sick syndrome (low-normal T3, normal T4, normal TSH)", "Primary hypothyroidism", "None"]', 1, 'The body slows metabolism to conserve energy. (MGH Pocket)'),
    (v_topic_id, '130: What is the most common trigger for a binge episode in Bulimia Nervosa?",', '["Hunger", "Negative affect (e.g., sadness, anxiety) or interpersonal stress", "Happiness", "None"]', 1, 'Bingeing serves as a maladaptive emotional regulation strategy. (Kaplan & Sadock)'),
    (v_topic_id, '131: How is the severity of Anorexia Nervosa classified in DSM-5?",', '["By frequency of purging", "By Body Mass Index (BMI)", "By caloric intake", "None"]', 1, 'Mild > 17, Moderate 16-16.9, Severe 15-15.9, Extreme < 15. (First Aid)'),
    (v_topic_id, '132: How is the severity of Bulimia Nervosa classified in DSM-5?",', '["By BMI", "By the frequency of inappropriate compensatory behaviors per week", "By weight", "None"]', 1, 'Mild 1-3, Moderate 4-7, Severe 8-13, Extreme 14+. (MGH Pocket)'),
    (v_topic_id, '133: A patient with Bulimia Nervosa presents with muscle weakness. What is the most likely cause?",', '["Atrophy", "Hypokalemia from recurrent vomiting or laxative abuse", "Hypercalcemia", "None"]', 1, 'Requires immediate ECG and electrolyte replacement. (Kaplan & Sadock)'),
    (v_topic_id, '134: What is the goal of nutritional rehabilitation in Anorexia Nervosa?",', '["Rapid weight gain", "Gradual weight restoration to avoid Refeeding Syndrome, aiming for 1-2 lbs per week", "Maintenance", "None"]', 1, 'Slow and steady prevents fatal electrolyte shifts. (First Aid)'),
    (v_topic_id, '135: A patient with ARFID refuses to eat because they are terrified of choking. This is an example of:",', '["Sensory aversion", "Aversion based on a feared consequence of eating", "Anorexia", "None"]', 1, 'Different from restricting to lose weight. (MGH Pocket)'),
    (v_topic_id, '136: Which demographic is most commonly affected by Anorexia Nervosa?",', '["Elderly men", "Adolescent and young adult females", "Middle-aged women", "None"]', 1, 'Onset typically during puberty or transition to college. (Kaplan & Sadock)'),
    (v_topic_id, '137: A patient with Anorexia Nervosa has elevated BUN. What is the most likely cause?",', '["Kidney failure", "Dehydration (pre-renal azotemia) due to fluid restriction or purging", "Liver failure", "None"]', 1, 'Always check hydration status. (First Aid)'),
    (v_topic_id, '138: What happens to cholesterol levels in Anorexia Nervosa?",', '["They decrease", "Paradoxical hypercholesterolemia", "They are zero", "None"]', 1, 'Due to altered hepatic metabolism despite low fat intake. (MGH Pocket)'),
    (v_topic_id, '139: Which brain structure is often implicated in the altered reward processing seen in eating disorders?",', '["Cerebellum", "The striatum and altered dopamine signaling", "Brainstem", "None"]', 1, 'Food may not trigger the same reward response in Anorexia. (Kaplan & Sadock)'),
    (v_topic_id, '140: A patient with Binge-Eating Disorder is seeking treatment. What is the primary recommendation?",', '["Bariatric surgery", "Cognitive Behavioral Therapy (CBT)", "Fasting", "None"]', 1, 'Treat the psychological disorder first. (First Aid)'),
    (v_topic_id, '141: What is "Orthorexia"?",', '["Fear of bones", "An unhealthy obsession with eating ''''pure'''' or ''''healthy'''' foods, often leading to severe dietary restriction (not an official DSM-5 diagnosis but clinically relevant)", "Eating dirt", "None"]', 1, 'The focus is on food quality, not necessarily weight loss. (MGH Pocket)'),
    (v_topic_id, '142: A patient with Anorexia Nervosa has a DXA scan showing osteoporosis. What is the recommended treatment?",', '["Bisphosphonates", "Weight restoration; bisphosphonates are generally avoided in young women of childbearing age due to teratogenicity", "Estrogen", "None"]', 1, 'Weight gain is the only proven way to restore bone health. (Kaplan & Sadock)'),
    (v_topic_id, '143: What is the most common psychiatric comorbidity in patients with Binge-Eating Disorder?",', '["Schizophrenia", "Major Depressive Disorder and Specific Phobias", "Bipolar I", "None"]', 1, 'High rates of mood and anxiety disorders. (First Aid)'),
    (v_topic_id, '144: A patient with Bulimia Nervosa has normal electrolytes but you suspect vomiting. What urine test is helpful?",', '["Urine sodium", "Urine chloride (will be low if vomiting due to renal conservation of chloride)", "Urine potassium", "None"]', 1, 'A helpful diagnostic pearl. (MGH Pocket)'),
    (v_topic_id, '145: Which eating disorder is most likely to have a normal or slightly elevated Body Mass Index (BMI)?",', '["Anorexia Restricting Type", "Bulimia Nervosa", "Anorexia Binge/Purge Type", "None"]', 1, 'The defining difference from Anorexia. (Kaplan & Sadock)'),
    (v_topic_id, '146: What happens to cortisol levels in Anorexia Nervosa?",', '["They drop", "They are elevated (hypercortisolemia) due to the chronic stress of starvation", "They are normal", "None"]', 1, 'Contributes to bone loss. (First Aid)'),
    (v_topic_id, '147: A patient with Pica eats clay. What is this specific behavior called?",', '["Pagophagia", "Geophagia", "Amylophagia", "None"]', 1, 'Often linked to iron deficiency. (MGH Pocket)'),
    (v_topic_id, '148: A patient with Pica eats ice. What is this specific behavior called?",', '["Geophagia", "Pagophagia", "Amylophagia", "None"]', 1, 'Highly specific for iron deficiency anemia. (Kaplan & Sadock)'),
    (v_topic_id, '149: What is the risk of using laxatives long-term for weight control?",', '["None", "Development of a ''''cathartic colon'''' (atonic colon requiring laxatives to function)", "Colon cancer", "None"]', 1, 'Causes severe, chronic constipation when stopped. (First Aid)'),
    (v_topic_id, '150: In the treatment of Bulimia, how does Fluoxetine help?",', '["Causes weight loss", "Reduces the frequency of bingeing and purging episodes, independent of its antidepressant effect", "Causes sedation", "None"]', 1, 'Often requires higher doses than used for depression. (MGH Pocket)'),
    (v_topic_id, '151: A patient with Anorexia Nervosa is admitted to the medical floor. What is the most critical monitoring parameter during the first week?",', '["Blood pressure", "Serum electrolytes (especially phosphorus, potassium, and magnesium) to detect Refeeding Syndrome", "Glucose", "None"]', 1, 'Refeeding syndrome can be rapidly fatal. (Kaplan & Sadock)'),
    (v_topic_id, '152: What is the role of the dietitian in treating eating disorders?",', '["To prescribe diets", "To provide nutritional education, establish meal plans, and challenge food myths as part of a multidisciplinary team", "To force feeding", "None"]', 1, 'A crucial team member alongside the psychiatrist and therapist. (First Aid)'),
    (v_topic_id, '153: Can a patient be diagnosed with both Anorexia Nervosa and Bulimia Nervosa simultaneously?",', '["Yes", "No. If the patient is significantly underweight (BMI < 18.5), the diagnosis is Anorexia Nervosa (binge-eating/purging type)", "None", "None"]', 1, 'Anorexia trumps Bulimia in the diagnostic hierarchy. (MGH Pocket)'),
    (v_topic_id, '154: A patient with ARFID has significant weight loss but no fear of gaining weight. What differentiates ARFID from Anorexia?",', '["Age of onset", "The absence of body image disturbance and the absence of an intense fear of gaining weight", "Gender", "None"]', 1, 'The core psychological pathology of Anorexia is missing. (Kaplan & Sadock)'),
    (v_topic_id, '155: What is the recommended treatment for Pica?",', '["Surgery", "Behavioral modification and treatment of underlying nutritional deficiencies (e.g., iron supplementation)", "SSRIs", "None"]', 1, 'Correcting the anemia often stops the craving for ice/clay. (First Aid)'),
    (v_topic_id, '156: A patient with Anorexia Nervosa complains of feeling cold all the time. What is the physiological reason?",', '["Fever", "Loss of insulating subcutaneous fat and decreased metabolic rate (decreased T3)", "Infection", "None"]', 1, 'A natural adaptation to starvation. (MGH Pocket)'),
    (v_topic_id, '157: What is the most common cause of death in Anorexia Nervosa?",', '["Infection", "Cardiac complications (arrhythmias due to hypokalemia/prolonged QTc) and Suicide", "Starvation", "None"]', 1, 'Medical instability and severe depression are the dual threats. (Kaplan & Sadock)'),
    (v_topic_id, '158: A patient with Bulimia Nervosa has a normal BMI. Why do they often seek treatment?",', '["For weight loss", "The binge/purge cycle is highly egodystonic (causes severe guilt, shame, and distress)", "For weight gain", "None"]', 1, 'Unlike Anorexia (restricting type), they want the behavior to stop. (First Aid)'),
    (v_topic_id, '159: What is the difference between Rumination Disorder and vomiting?",', '["They are the same", "Rumination is typically effortless, non-nauseating regurgitation, whereas vomiting is forceful and accompanied by nausea", "None", "None"]', 1, 'Rumination is often soothing to the patient. (MGH Pocket)'),
    (v_topic_id, '160: A patient with Anorexia Nervosa presents with bradycardia (HR 45). What is the appropriate treatment?",', '["Atropine", "Weight restoration; the bradycardia is a physiological adaptation and usually requires no specific cardiac medication unless symptomatic/unstable", "Pacemaker", "None"]', 1, 'The heart slows down to save energy. (Kaplan & Sadock)'),
    (v_topic_id, '161: Which medication is sometimes used to stimulate appetite in patients with Anorexia Nervosa (off-label)?",', '["Fluoxetine", "Olanzapine or Mirtazapine", "Lithium", "None"]', 1, 'Both can promote weight gain and help with anxiety/sleep. (First Aid)'),
    (v_topic_id, '162: What is the relationship between Anorexia Nervosa and athletic performance?",', '["Improves it", "Initially, patients may feel energetic, but chronic starvation inevitably leads to decreased performance, injuries, and fatigue", "No effect", "None"]', 1, 'The Female Athlete Triad is a major concern. (MGH Pocket)'),
    (v_topic_id, '163: A patient with Binge-Eating Disorder reports eating large amounts of food when not physically hungry. Is this a diagnostic criterion?",', '["No", "Yes, eating when not hungry is one of the specific features associated with BED", "None", "None"]', 1, 'Emotional eating rather than physiological eating. (Kaplan & Sadock)'),
    (v_topic_id, '164: How does cognitive behavioral therapy (CBT) address the cognitive distortions in eating disorders?",', '["By ignoring them", "By identifying irrational thoughts (e.g., ''''If I eat one cookie, I will gain 10 pounds'''') and challenging them with evidence", "By agreeing", "None"]', 1, 'Restructuring the thought process. (First Aid)'),
    (v_topic_id, '165: A patient with Anorexia Nervosa refuses to eat, claiming they will instantly become obese. This is an example of:",', '["Psychosis", "A non-bizarre overvalued idea or delusional-level body image distortion", "Malingering", "None"]', 1, 'The distortion can be so severe it borders on psychosis. (MGH Pocket)'),
    (v_topic_id, '166: What is the prevalence of Bulimia Nervosa compared to Anorexia Nervosa?",', '["Bulimia is rarer", "Bulimia Nervosa is more prevalent than Anorexia Nervosa in the general population", "They are equal", "None"]', 1, 'BED is the most prevalent, followed by Bulimia, then Anorexia. (Kaplan & Sadock)'),
    (v_topic_id, '167: A patient with an eating disorder has a history of childhood sexual abuse. How common is this association?",', '["Rare", "High; trauma and abuse are significant risk factors for the development of eating disorders (especially Bulimia and BED)", "None", "None"]', 1, 'Trauma-informed care is essential. (First Aid)'),
    (v_topic_id, '168: What is the role of family dynamics in Anorexia Nervosa?",', '["No role", "Families are often described as enmeshed, rigid, and overprotective (Minuchin''s theory), though FBT avoids blaming the family", "None", "None"]', 1, 'The illness often serves to deflect attention from family conflicts. (MGH Pocket)'),
    (v_topic_id, '169: A patient with ARFID requires a feeding tube because they refuse all solid food. Does this meet criteria for ARFID?",', '["No", "Yes, dependence on enteral feeding or oral nutritional supplements is a key criterion for ARFID", "None", "None"]', 1, 'Signifies severe nutritional impairment. (Kaplan & Sadock)'),
    (v_topic_id, '170: What is the prognosis for Binge-Eating Disorder?",', '["Poor", "Generally better than Anorexia or Bulimia; many patients achieve remission with CBT and weight management interventions", "Fatal", "None"]', 1, 'Highly responsive to targeted therapy. (First Aid)'),
    (v_topic_id, '171: A patient with Bulimia Nervosa has chronic sore throat and hoarseness. What is the cause?",', '["Infection", "Repeated exposure of the vocal cords to gastric acid from self-induced vomiting", "Allergies", "None"]', 1, 'A common ENT complaint in purging. (MGH Pocket)'),
    (v_topic_id, '172: What is the risk of rapid IV fluid administration in a severely malnourished Anorexia patient?",', '["None", "Can precipitate heart failure; the atrophied heart muscle cannot handle the sudden increase in preload", "Dehydration", "None"]', 1, 'Fluids must be given cautiously. (Kaplan & Sadock)'),
    (v_topic_id, '173: A patient with Anorexia Nervosa has elevated liver enzymes (AST/ALT). What is the mechanism?",', '["Alcohol abuse", "Starvation-induced hepatic autophagy or fatty infiltration (steatosis)", "Hepatitis C", "None"]', 1, 'Usually normalizes with weight restoration. (First Aid)'),
    (v_topic_id, '174: What is the "Maudsley Method"?', '["A surgery", "Another name for Family-Based Treatment (FBT), the gold-standard therapy for adolescent Anorexia Nervosa", "A medication", "None"]', 1, 'Developed at the Maudsley Hospital in London. (MGH Pocket)'),
    (v_topic_id, '175: A patient with Bulimia Nervosa presents with constipation after trying to stop laxatives. What is the best management?",', '["More laxatives", "Patient education, hydration, high-fiber diet, and possibly osmotic agents (e.g., Miralax) to slowly retrain the bowel", "Surgery", "None"]', 1, 'Avoid stimulant laxatives. (Kaplan & Sadock)'),
    (v_topic_id, '176: Which eating disorder is most frequently associated with impulsivity (e.g., shoplifting, promiscuity, substance abuse)?",', '["Anorexia Restricting", "Bulimia Nervosa", "ARFID", "None"]', 1, 'Bingeing is just one manifestation of their general impulsivity. (First Aid)'),
    (v_topic_id, '177: What happens to the salivary glands in Bulimia Nervosa?",', '["They shrink", "They undergo non-inflammatory hypertrophy (sialadenosis) leading to a ''''chipmunk'''' appearance", "They become infected", "None"]', 1, 'Reversible with cessation of vomiting. (MGH Pocket)'),
    (v_topic_id, '178: A patient with Anorexia Nervosa is found to have a low white blood cell count (leukopenia). Are they at high risk for opportunistic infections?",', '["Yes", "Surprisingly no; despite the leukopenia, severe infections are relatively uncommon in Anorexia unless extremely advanced", "None", "None"]', 1, 'A clinical paradox. (Kaplan & Sadock)'),
    (v_topic_id, '179: What is the primary difference between Anorexia Nervosa and Major Depressive Disorder (MDD) presenting with weight loss?",', '["MDD patients are heavier", "In MDD, weight loss is due to lack of appetite/energy. In Anorexia, the patient is intensely afraid of gaining weight and intentionally restricts.", "They are the same", "None"]', 1, 'Intent and body image differentiate them. (First Aid)'),
    (v_topic_id, '180: A patient with Binge-Eating Disorder eats secretly because they are embarrassed by how much they eat. Is this typical?",', '["No", "Yes, eating alone due to embarrassment is a specific diagnostic criterion for BED", "None", "None"]', 1, 'Shame is a central feature of the disorder. (MGH Pocket)'),
    (v_topic_id, '181: Which psychiatric disorder has the highest mortality rate?', '["Schizophrenia", "Anorexia Nervosa", "Bipolar Disorder", "Major Depressive Disorder"]', 1, 'Anorexia has the highest mortality rate of any psychiatric disorder due to starvation, cardiac complications, and suicide. (First Aid)'),
    (v_topic_id, '182: A patient with Bulimia Nervosa admits to using diuretics to lose weight. What electrolyte abnormality is expected?', '["Hyperkalemia", "Hypokalemia and hyponatremia", "Hypercalcemia", "None"]', 1, 'Diuretics waste potassium and sodium. (Kaplan & Sadock)'),
    (v_topic_id, '183: What is the most appropriate setting for treating a patient with Anorexia Nervosa whose BMI is 13 and who is medically unstable?', '["Outpatient clinic", "Inpatient medical unit or specialized eating disorder unit", "Intensive outpatient program", "None"]', 1, 'Medical stabilization is the first priority. (MGH Pocket)'),
    (v_topic_id, '184: A patient with Anorexia Nervosa has yellow-orange skin on their palms and soles. What is the diagnosis?', '["Jaundice", "Carotenemia (due to excessive consumption of carotene-rich foods like carrots to avoid calories)", "Liver failure", "None"]', 1, 'Spares the sclera, unlike jaundice. (First Aid)'),
    (v_topic_id, '185: Which eating disorder is characterized by eating large amounts of food rapidly, feeling uncomfortably full, and experiencing significant distress, WITHOUT purging?', '["Bulimia Nervosa", "Binge-Eating Disorder", "Anorexia Nervosa", "ARFID"]', 1, 'The absence of compensatory behaviors is the key. (Kaplan & Sadock)'),
    (v_topic_id, '186: What is the role of psychoeducation in the treatment of eating disorders?', '["It is useless", "It is a crucial component to teach patients about the physiological effects of starvation and purging, helping them understand their symptoms", "None", "None"]', 1, 'Knowledge empowers recovery. (MGH Pocket)'),
    (v_topic_id, '187: A patient with Avoidant/Restrictive Food Intake Disorder (ARFID) is most likely to avoid food due to:', '["Fear of gaining weight", "Sensory characteristics of food (e.g., texture, smell) or fear of aversive consequences (e.g., choking)", "Desire to be thin", "None"]', 1, 'The motivation is not body image related. (First Aid)'),
    (v_topic_id, '188: What is the typical age of onset for Bulimia Nervosa?', '["Childhood", "Late adolescence or early adulthood", "Middle age", "Late adulthood"]', 1, 'Often starts slightly later than Anorexia. (Kaplan & Sadock)'),
    (v_topic_id, '189: A patient with Anorexia Nervosa is undergoing nutritional rehabilitation. They suddenly develop acute heart failure and pulmonary edema. What is the most likely cause?', '["Myocardial infarction", "Refeeding Syndrome (hypophosphatemia)", "Pneumonia", "None"]', 1, 'The hallmark complication of rapid refeeding. (MGH Pocket)'),
    (v_topic_id, '190: Which therapy emphasizes interpersonal problem-solving and has been shown to be effective for Bulimia Nervosa, albeit slower to act than CBT?', '["Psychoanalysis", "Interpersonal Psychotherapy (IPT)", "Exposure therapy", "None"]', 1, 'Focuses on relationship issues that trigger binges. (First Aid)'),
    (v_topic_id, '191: What is the most common method of purging in Bulimia Nervosa?', '["Laxatives", "Self-induced vomiting", "Diuretics", "Enemas"]', 1, 'The most direct and frequent method used to prevent weight gain. (Kaplan & Sadock)'),
    (v_topic_id, '192: A patient with Pica is found to have iron deficiency anemia. What is the most appropriate treatment?', '["Antipsychotics", "Iron supplementation and behavioral therapy", "SSRIs", "None"]', 1, 'Correcting the deficiency often resolves the Pica. (MGH Pocket)'),
    (v_topic_id, '193: What is the relationship between Eating Disorders and Substance Use Disorders?', '["No relationship", "Highly comorbid; especially in Bulimia Nervosa and Binge-Eating Disorder (shared impulsivity/reward pathway dysfunction)", "None", "None"]', 1, 'Dual diagnosis requires integrated treatment. (First Aid)'),
    (v_topic_id, '194: A patient with Anorexia Nervosa has an intense fear of gaining weight. Is this fear rational or irrational?', '["Rational", "Irrational and deeply entrenched, often persisting even when the patient is severely emaciated", "None", "None"]', 1, 'A core feature of the pathology. (Kaplan & Sadock)'),
    (v_topic_id, '195: What is the prognosis for ARFID?', '["Fatal", "Generally good with targeted behavioral interventions (e.g., exposure therapy for sensory aversions or trauma)", "Poor", "None"]', 1, 'Highly treatable with specialized care. (MGH Pocket)'),
    (v_topic_id, '196: A patient with Bulimia Nervosa exercises for 3 hours every time they eat a dessert. Is this a compensatory behavior?', '["No", "Yes, excessive exercise is considered a non-purging compensatory behavior in Bulimia", "None", "None"]', 1, 'The exercise is driven by compulsion, not fitness. (First Aid)'),
    (v_topic_id, '197: Which medication is FDA-approved for the treatment of Anorexia Nervosa?', '["Fluoxetine", "None. No medications are FDA-approved specifically for Anorexia Nervosa.", "Olanzapine", "None"]', 1, 'Treatment relies on nutritional rehab and therapy. (Kaplan & Sadock)'),
    (v_topic_id, '198: A patient with Rumination Disorder repeatedly regurgitates food. What distinguishes this from vomiting?', '["Nausea", "Rumination is typically effortless, non-nauseating, and the food may be re-chewed and swallowed", "It is the same", "None"]', 1, 'A distinct behavioral pattern. (MGH Pocket)'),
    (v_topic_id, '199: What is the effect of severe malnutrition on the brain in Anorexia Nervosa?', '["Tumors", "Cerebral atrophy, enlarged ventricles, and cognitive impairment (often reversible with weight restoration)", "Hemorrhage", "None"]', 1, 'The brain literally shrinks from starvation. (First Aid)'),
    (v_topic_id, '200: A patient with Binge-Eating Disorder is considering bariatric surgery. What is the psychiatric recommendation?', '["Do it immediately", "Treat the BED first; bariatric surgery without addressing the underlying eating disorder often leads to poor outcomes or symptom substitution", "None", "None"]', 1, 'Surgery fixes the stomach, not the mind. (Kaplan & Sadock)'),
    (v_topic_id, '201: A patient with Anorexia Nervosa is admitted with a potassium level of 2.1 mEq/L. What is the most appropriate next step?', '["Prescribe a banana", "Immediate IV potassium replacement with continuous ECG monitoring", "Give oral potassium supplements", "None"]', 1, 'Severe hypokalemia is a medical emergency with high risk of fatal arrhythmias. (First Aid)'),
    (v_topic_id, '202: Which eating disorder has the latest average age of onset?', '["Anorexia Nervosa", "Binge-Eating Disorder (BED)", "Bulimia Nervosa", "ARFID"]', 1, 'BED typically presents in older adolescents and adults. (MGH Pocket)'),
    (v_topic_id, '203: A patient with Bulimia Nervosa develops a severe, unilateral, painful swelling of the face after an episode of purging. What is the most likely complication?', '["Mumps", "Acute suppurative sialadenitis (bacterial infection of the parotid gland due to stasis and retrograde bacterial ascension)", "Tumor", "None"]', 1, 'Different from the chronic, painless, bilateral sialadenosis. Requires antibiotics. (Kaplan & Sadock)'),
    (v_topic_id, '204: What is the defining characteristic of "Atypical Anorexia Nervosa"?', '["They binge eat", "All criteria for Anorexia Nervosa are met EXCEPT that despite significant weight loss, the individual''s weight is within or above the normal range", "They don''t fear weight gain", "None"]', 1, 'A category under OSFED (Other Specified Feeding or Eating Disorder). (DSM-5)'),
    (v_topic_id, '205: A 250 lb patient loses 100 lbs rapidly through extreme starvation and now presents with amenorrhea, bradycardia, and intense fear of gaining weight. BMI is 24. Diagnosis?', '["Anorexia Nervosa", "Atypical Anorexia Nervosa", "Bulimia Nervosa", "None"]', 1, 'They suffer the same medical complications of starvation, despite not being technically "underweight." (First Aid)'),
    (v_topic_id, '206: Which eating disorder is most common in patients seeking bariatric surgery?', '["Anorexia Nervosa", "Binge-Eating Disorder (BED)", "Bulimia Nervosa", "Pica"]', 1, 'Prevalence of BED is significantly higher in weight-loss clinics than in the general population. (MGH Pocket)'),
    (v_topic_id, '207: What is the relationship between Anorexia Nervosa and genetics?', '["No genetic link", "High heritability; first-degree relatives have a significantly higher risk of developing an eating disorder", "100% genetic", "None"]', 1, 'Strong genetic components exist alongside environmental factors. (Kaplan & Sadock)'),
    (v_topic_id, '208: A patient with Anorexia Nervosa presents with constipation. What is the pathophysiology?', '["Too much fiber", "Decreased gastrointestinal motility and delayed gastric emptying due to starvation and autonomic dysfunction", "Bowel obstruction", "None"]', 1, 'The gut essentially "goes to sleep" to save energy. (First Aid)'),
    (v_topic_id, '209: What is the most appropriate initial management for starvation-induced constipation in Anorexia Nervosa?', '["Stimulant laxatives", "Nutritional rehabilitation and hydration; avoid stimulant laxatives to prevent dependence", "Surgery", "None"]', 1, 'The bowel will wake up once it receives consistent nutrition. (MGH Pocket)'),
    (v_topic_id, '210: A patient with Bulimia Nervosa has a calloused area on the back of their hand. What is this called?', '["Homan''s sign", "Russell''s sign", "Chvostek''s sign", "Trousseau''s sign"]', 1, 'Classic indicator of self-induced vomiting. (Kaplan & Sadock)'),
    (v_topic_id, '211: What is the "set-point theory" of body weight regulation?', '["Weight is completely controllable", "The body has a biologically determined weight range that it vigorously defends through metabolic and hormonal adaptations", "Weight is purely genetic", "None"]', 1, 'Explains why severe diets often fail and lead to rebound weight gain or bingeing. (First Aid)'),
    (v_topic_id, '212: How does the body defend its set-point during starvation?', '["Increasing metabolism", "Decreasing basal metabolic rate, increasing hunger hormones (ghrelin), and decreasing satiety hormones (leptin)", "Stopping digestion", "None"]', 1, 'A survival mechanism evolved over millennia. (MGH Pocket)'),
    (v_topic_id, '213: A patient with Anorexia Nervosa has a low core body temperature (hypothermia). Why?', '["Infection", "Loss of insulating body fat and decreased metabolic heat production", "Excessive sweating", "None"]', 1, 'A physiological consequence of starvation. (Kaplan & Sadock)'),
    (v_topic_id, '214: What is the primary psychological defense mechanism used by patients with Bulimia Nervosa?', '["Denial", "Rationalization and isolation of affect", "Sublimation", "None"]', 1, 'They know the behavior is abnormal but rationalize it as a necessary evil to control weight. (First Aid)'),
    (v_topic_id, '215: A patient with Avoidant/Restrictive Food Intake Disorder (ARFID) presents with scurvy. What is the underlying cause?', '["Infection", "Severe nutritional deficiency (Vitamin C) due to an extremely restricted repertoire of accepted foods", "Genetics", "None"]', 1, 'ARFID can lead to classic malnutrition syndromes without body image distortion. (MGH Pocket)'),
    (v_topic_id, '216: What is the risk of suicide in Bulimia Nervosa?",', '["None", "Elevated, especially given the high comorbidity with Borderline Personality Disorder and Major Depressive Disorder", "Very low", "None"]', 1, 'Always assess for suicidal ideation. (Kaplan & Sadock)'),
    (v_topic_id, '217: A patient with Anorexia Nervosa develops a pericardial effusion. What is the most likely cause?",', '["Infection", "Severe hypoalbuminemia and starvation-induced myocardial atrophy", "Trauma", "None"]', 1, 'Fluid shifts occur due to low oncotic pressure. (First Aid)'),
    (v_topic_id, '218: Which brain imaging finding is associated with severe, chronic Anorexia Nervosa?",', '["Microcephaly", "Cortical pseudoatrophy and ventricular enlargement, which is often partially or fully reversible with weight gain", "Tumor", "None"]', 1, 'The brain loses mass during starvation. (MGH Pocket)'),
    (v_topic_id, '219: What is the role of the primary care physician in managing eating disorders?",', '["None", "Crucial for medical monitoring (weight, vitals, ECG, electrolytes) and coordinating care with the psychiatric team", "To prescribe diets", "None"]', 1, 'Eating disorders are highly medicalized psychiatric illnesses. (Kaplan & Sadock)'),
    (v_topic_id, '220: A patient with Bulimia Nervosa is pregnant. What are the maternal/fetal risks?",', '["None", "Increased risk of miscarriage, preterm birth, low birth weight, and postpartum depression", "Twins", "None"]', 1, 'Pregnancy is a high-risk period requiring close monitoring. (First Aid)'),
    (v_topic_id, '221: What happens to cognitive function in a severely malnourished Anorexia patient?",', '["Improves", "Significant impairment in concentration, memory, and executive function, which resolves with refeeding", "Permanent damage", "None"]', 1, 'You cannot do effective psychotherapy on a starved brain. (MGH Pocket)'),
    (v_topic_id, '222: Which eating disorder is characterized by eating large amounts of food in secret, feeling a loss of control, and NOT purging?",', '["Bulimia Nervosa", "Binge-Eating Disorder (BED)", "Anorexia Nervosa", "ARFID"]', 1, 'The classic presentation of BED. (Kaplan & Sadock)'),
    (v_topic_id, '223: What is the cornerstone of treating Binge-Eating Disorder?",', '["Surgery", "Cognitive Behavioral Therapy (CBT) tailored for binge eating", "Fasting", "None"]', 1, 'Medications are adjunctive. (First Aid)'),
    (v_topic_id, '224: A patient with Anorexia Nervosa is terrified of eating a slice of pizza. How does CBT approach this?",', '["By ignoring it", "Through graded exposure and response prevention (eating the pizza and preventing the compensatory behavior)", "By giving them an apple", "None"]', 1, 'Exposure therapy principles apply to food fears. (MGH Pocket)'),
    (v_topic_id, '225: What is "Night Eating Syndrome"?', '["Eating early", "Recurrent episodes of night eating (waking from sleep to eat or excessive food consumption after the evening meal) with awareness and distress", "Sleepwalking", "None"]', 1, 'Differentiated from sleep-related eating disorder (which lacks awareness). (Kaplan & Sadock)'),
    (v_topic_id, '226: How does Night Eating Syndrome differ from Sleep-Related Eating Disorder (SRED)?",', '["They are the same", "In NES, the patient is AWAKE and fully aware of the eating. In SRED, the patient is ASLEEP (a parasomnia) and has amnesia for the event.", "None", "None"]', 1, 'Amnesia is the key differentiator. (First Aid)'),
    (v_topic_id, '227: A patient with Anorexia Nervosa has acrocyanosis. What does this look like?",', '["Red face", "Blue, cold, and often sweaty hands and feet", "Yellow eyes", "None"]', 1, 'A result of poor peripheral circulation. (MGH Pocket)'),
    (v_topic_id, '228: What is the impact of Anorexia Nervosa on the immune system?",', '["Hyperactivity", "Mild immune suppression, though overt clinical infections are surprisingly rare unless malnutrition is extreme", "No effect", "None"]', 1, 'Another physiological paradox of the disorder. (Kaplan & Sadock)'),
    (v_topic_id, '229: A patient with Bulimia Nervosa admits to chewing and spitting out large amounts of food without swallowing. Does this count as a compensatory behavior?",', '["No", "Yes, ''''chew and spit'''' is a common non-purging compensatory behavior", "None", "None"]', 1, 'A variation of disordered eating to experience the taste without the calories. (First Aid)'),
    (v_topic_id, '230: What is the best approach when a patient with Anorexia Nervosa refuses to be weighed?",', '["Force them", "Establish a clear, non-negotiable protocol (e.g., blind weigh-ins) and validate their anxiety, emphasizing that medical safety requires monitoring", "Let them skip it", "None"]', 1, 'Consistent boundaries are essential. (MGH Pocket)'),
    (v_topic_id, '231: A patient with Pica has a compulsion to eat soil. This is specifically termed:",', '["Pagophagia", "Geophagia", "Amylophagia", "None"]', 1, 'Common in certain cultures and often linked to iron/zinc deficiency. (Kaplan & Sadock)'),
    (v_topic_id, '232: A patient with Pica has a compulsion to eat raw starch. This is specifically termed:",', '["Geophagia", "Amylophagia", "Pagophagia", "None"]', 1, 'Another specific presentation of Pica. (First Aid)'),
    (v_topic_id, '233: What is the role of deeply analyzing childhood trauma during the ACUTE stabilization phase of Anorexia Nervosa?",', '["It is the primary goal", "It is generally contraindicated; acute treatment focuses on nutritional stabilization and behavioral symptom management", "It cures them", "None"]', 1, 'Deep trauma work requires a nourished, stable brain. (MGH Pocket)'),
    (v_topic_id, '234: Which medication class is known to cause significant weight gain and may precipitate binge eating in susceptible individuals?",', '["Stimulants", "Atypical antipsychotics (e.g., Olanzapine, Clozapine)", "SSRIs", "None"]', 1, 'A major metabolic side effect. (Kaplan & Sadock)'),
    (v_topic_id, '235: A patient with Binge-Eating Disorder has severe obesity. What is the most important clinical consideration regarding their weight?",', '["Immediate weight loss", "The psychological distress and eating disorder pathology should be treated before implementing aggressive weight loss interventions", "Ignore the weight", "None"]', 1, 'Dieting often exacerbates binge eating. (First Aid)'),
    (v_topic_id, '236: What is the "Minnesota Starvation Experiment"?', '["A diet plan", "A landmark WWII study showing that healthy men subjected to severe caloric restriction developed obsessive thoughts about food, depression, and bizarre eating rituals (mirroring Anorexia)", "None", "None"]', 1, 'Proved that starvation ITSELF causes the psychological symptoms of eating disorders. (MGH Pocket)'),
    (v_topic_id, '237: A patient with Bulimia Nervosa presents with a Mallory-Weiss tear. What is the typical clinical presentation?",', '["Massive bleeding", "Painless hematemesis following an episode of forceful retching or vomiting", "Chest pain", "None"]', 1, 'A mucosal tear. (Kaplan & Sadock)'),
    (v_topic_id, '238: A patient with Bulimia Nervosa presents with Boerhaave syndrome. What is the typical clinical presentation?",', '["Painless bleeding", "Sudden, excruciating chest/abdominal pain and subcutaneous emphysema (crepitus) following forceful vomiting", "Fever", "None"]', 1, 'A transmural rupture. A surgical emergency. (First Aid)'),
    (v_topic_id, '239: What is "Purging Disorder"?', '["Bulimia", "Recurrent purging behavior to influence weight/shape in the ABSENCE of binge eating", "Anorexia", "None"]', 1, 'Classified under OSFED in DSM-5. (MGH Pocket)'),
    (v_topic_id, '240: How does Purging Disorder differ from Bulimia Nervosa?",', '["It doesn''t", "Purging Disorder lacks the BINGE eating episodes required for a Bulimia diagnosis", "It is worse", "None"]', 1, 'They eat normal or small amounts, then purge. (Kaplan & Sadock)'),
    (v_topic_id, '241: A patient with Anorexia Nervosa restricts their fluid intake to lose water weight. What is the danger?",', '["None", "Severe dehydration leading to acute kidney injury (prerenal azotemia), hypotension, and cardiovascular collapse", "Weight gain", "None"]', 1, 'A very dangerous form of restriction. (First Aid)'),
    (v_topic_id, '242: A patient with Anorexia Nervosa drinks massive amounts of water before weigh-ins. This is called:",', '["Hydration", "Water loading; a deceptive behavior used to artificially inflate their weight on the scale", "Pica", "None"]', 1, 'Can lead to dangerous dilutional hyponatremia and seizures. (MGH Pocket)'),
    (v_topic_id, '243: How do you prevent a patient from successfully "water loading" prior to a weigh-in?",', '["Don''t weigh them", "Require them to empty their bladder immediately before being weighed, and monitor fluid intake closely", "Yell at them", "None"]', 1, 'Standard protocol in eating disorder units. (Kaplan & Sadock)'),
    (v_topic_id, '244: What is the primary difference between early-onset (childhood) and adult-onset Anorexia Nervosa?",', '["No difference", "Early-onset often presents with failure to make expected weight gains and severely stunts growth/pubertal development; adult-onset presents with weight loss", "None", "None"]', 1, 'Children may not "lose" weight, they just stop growing. (First Aid)'),
    (v_topic_id, '245: A patient with Bulimia Nervosa is started on Fluoxetine. What is the recommended dose?",', '["10 mg/day", "60 mg/day; significantly higher than the standard starting dose for depression", "100 mg/day", "None"]', 1, 'High doses are needed for the anti-bulimic effect. (MGH Pocket)'),
    (v_topic_id, '246: Which therapy for eating disorders involves keeping a detailed "food diary" tracking meals, binges, purges, and associated emotions?",', '["Psychoanalysis", "Cognitive Behavioral Therapy (CBT-E)", "EMDR", "None"]', 1, 'Self-monitoring is a core component of CBT. (Kaplan & Sadock)'),
    (v_topic_id, '247: A patient with ARFID avoids all crunchy foods because they choked on a carrot as a child. This is:",', '["Anorexia", "ARFID related to aversive consequences", "Bulimia", "None"]', 1, 'A trauma response, not a body image issue. (First Aid)'),
    (v_topic_id, '248: A patient with ARFID has absolutely no interest in eating and frequently forgets to eat. This is:",', '["Anorexia", "ARFID related to lack of interest in eating/food", "Bulimia", "None"]', 1, 'A distinct subtype of ARFID. (MGH Pocket)'),
    (v_topic_id, '249: What is the most important component of the physical exam for a patient suspected of having an eating disorder?",', '["Reflexes", "Orthostatic vital signs (blood pressure and heart rate lying vs standing) to assess for severe dehydration and autonomic dysfunction", "Vision test", "None"]', 1, 'Orthostasis is a major criterion for hospitalization. (Kaplan & Sadock)'),
    (v_topic_id, '250: Final Pearl: The core pathology of Anorexia Nervosa is:",', '["Wanting to be pretty", "An intense, delusional-level fear of gaining weight and a severe disturbance in the way one''s body weight or shape is experienced", "Wanting attention", "None"]', 1, 'It is a life-threatening psychiatric illness, not a lifestyle choice. (MediHelp Mastery)');
